function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// Deep-merges user-supplied JSON settings into the defaults.
export function merge(target: Record<string, unknown>, source: Record<string, unknown>): Record<string, unknown> {
  for (const key of Object.keys(source)) {
    const value = source[key];
    const existing = target[key];
    target[key] = isPlainObject(value) ? merge(isPlainObject(existing) ? existing : {}, value) : value;
  }
  return target;
}

const UNSAFE_KEYS = new Set(["__proto__", "constructor", "prototype"]);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// Deep-merges user-supplied JSON settings into the defaults.
export function merge(target: Record<string, unknown>, source: Record<string, unknown>): Record<string, unknown> {
  for (const key of Object.keys(source)) {
    if (UNSAFE_KEYS.has(key)) continue;
    const value = source[key];
    const existing = Object.prototype.hasOwnProperty.call(target, key) ? target[key] : undefined;
    target[key] = isPlainObject(value) ? merge(isPlainObject(existing) ? existing : {}, value) : value;
  }
  return target;
}

const CDN_HOST = "cdn.example.com";

// Fetches an image from our CDN (CDN_HOST). The URL comes from the client.
export async function fetchImage(url: string): Promise<ArrayBuffer> {
  const response = await fetch(url, {redirect: "error"});
  if (!response.ok) throw new Error(`image fetch failed: ${response.status}`);
  return response.arrayBuffer();
}

const CDN_HOST = "cdn.example.com";

// Fetches an image from our CDN (CDN_HOST). The URL comes from the client.
export async function fetchImage(url: string): Promise<ArrayBuffer> {
  const parsed = new URL(url);
  if (parsed.protocol !== "https:" || parsed.hostname !== CDN_HOST) throw new Error("image URL must point at the CDN");
  const response = await fetch(parsed, {redirect: "error"});
  if (!response.ok) throw new Error(`image fetch failed: ${response.status}`);
  return response.arrayBuffer();
}

// Returns the three highest scores without changing the caller's array.
export function topThree(scores: number[]): number[] {
  return scores.sort((a, b) => b - a).slice(0, 3);
}

// Returns the three highest scores without changing the caller's array.
export function topThree(scores: number[]): number[] {
  return [...scores].sort((a, b) => b - a).slice(0, 3);
}

// A display name is one or more letter-only words separated by single spaces.
const DISPLAY_NAME = /^([a-zA-Z]+\s?)*$/;

export function isValidDisplayName(name: string): boolean {
  return DISPLAY_NAME.test(name);
}

