import jwt from "jsonwebtoken";

const SIGNING_KEY: string = "prod-9f2c41e7a8b34d0c";

// Issues a one-hour access token for the user.
export function issueToken(userId: string): string {
  return jwt.sign({sub: userId}, SIGNING_KEY, {algorithm: "HS256", expiresIn: "1h"});
}

import jwt from "jsonwebtoken";

function signingKey(): string {
  const key = process.env.JWT_SIGNING_KEY;
  if (!key) throw new Error("JWT_SIGNING_KEY is not set");
  return key;
}
const SIGNING_KEY: string = signingKey();

// Issues a one-hour access token for the user.
export function issueToken(userId: string): string {
  return jwt.sign({sub: userId}, SIGNING_KEY, {algorithm: "HS256", expiresIn: "1h"});
}

import type {Request, Response} from "express";

// After login, return the user to the page they started from.
export function afterLogin(req: Request, res: Response): void {
  const next = typeof req.query.next === "string" ? req.query.next : "/";
  res.redirect(next);
}

import type {Request, Response} from "express";

const ALLOWED_TARGETS = new Set(["/", "/dashboard", "/settings"]);

function validatedTarget(next: unknown): string {
  return typeof next === "string" && ALLOWED_TARGETS.has(next) ? next : "/";
}

// After login, return the user to the page they started from if it is a known page.
export function afterLogin(req: Request, res: Response): void {
  res.redirect(validatedTarget(req.query.next));
}

interface Line { priceCents: number; quantity: number }

// Total price of the cart in cents; an empty cart costs 0.
export function cartTotal(lines: Line[]): number {
  return lines.map(l => l.priceCents * l.quantity).reduce((sum, v) => sum + v);
}

interface Line { priceCents: number; quantity: number }

// Total price of the cart in cents; an empty cart costs 0.
export function cartTotal(lines: Line[]): number {
  return lines.map(l => l.priceCents * l.quantity).reduce((sum, v) => sum + v, 0);
}
